document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll("sup[id^='fnref']");e.forEach(e=>{const n=e.querySelector("a");if(!n)return;const o=n.getAttribute("href")?.slice(1),s=document.getElementById(o);if(!s)return;const t=document.createElement("span");t.className="sidenote",t.innerHTML=s.innerHTML,e.after(t),n.addEventListener("click",e=>{window.matchMedia("(max-width: 768px)").matches&&(e.preventDefault(),t.classList.toggle("is-open"))})})})